      "name": "adoptSavedMeta",
      "source": "adoptSavedMeta(meta: PlayerMeta, bar: (string | null)[], level: number): void {\n    this.adoptSeatMeta(this.localSeat, meta, bar, level);\n    // The graft may have CHANGED the corpse ring (mode stage + own-ring\n    // records land here, after createPlayer's loadZone already spawned from\n    // fresh-character defaults) — re-spawn this zone's corpses from the truth.\n    this.spawnPlayerCorpses(this.zone);\n  }",
      "function": "export function sceneAdoptSavedMeta(nativeHost:Pick<NativeCharacterRestorationHost,\"adoptSeatMeta\"|\"localSeat\"|\"spawnPlayerCorpses\"|\"zone\">,meta: PlayerMeta, bar: (string | null)[], level: number): void {\n    nativeHost.adoptSeatMeta(nativeHost.localSeat, meta, bar, level);\n    // The graft may have CHANGED the corpse ring (mode stage + own-ring\n    // records land here, after createPlayer's loadZone already spawned from\n    // fresh-character defaults) — re-spawn this zone's corpses from the truth.\n    nativeHost.spawnPlayerCorpses(nativeHost.zone);\n  }",
      "sha256": "258ea677cd2bf1843f3188abbe67b56b1dd2963b0d2ec96a24ea2490e287bd56",
